INSERT INTO public.guidance_assets (id, rule_id, what, when_text, why, how, consequence, deep_link, generated_by, created_at, updated_at) VALUES ('guide_8678fe143ac7444288003c9af2c33cea', 'rule_1de98f8d058348058a174cc60173092f', 'Pay the $200 Freshman Enrollment Deposit.', 'As soon as possible after admission — it gates housing and orientation registration.', 'This deposit is how you tell Alabama you intend to enroll, and it''s applied toward your first semester''s tuition.', 'Log into myBama, go to the Admissions/Scholarships section, and select ''Submit Freshman Enrollment Deposit.''', 'You can''t apply for housing or register for Bama Bound orientation until this is paid.', 'https://admissions.ua.edu/freshman/deposit/', 'human', '2026-09-07T23:42:04.998Z', '2026-09-07T23:42:04.998Z');
INSERT INTO public.guidance_assets (id, rule_id, what, when_text, why, how, consequence, deep_link, generated_by, created_at, updated_at) VALUES ('guide_7494323f80864d849bd2d3794608cb87', 'rule_68c16db3487e45ef9072b4c41d2ff270', 'Submit your housing application before February 2.', 'By February 2, 2027 for the 2027-28 academic year, to be eligible for online room selection.', 'Applying after this date means Alabama assigns you a room instead of letting you pick one.', 'Complete the housing application and $175 housing deposit ($140 prepayment + $35 non-refundable fee) through the housing portal after your enrollment deposit is on file.', 'Miss it and you lose the ability to choose your own room and roommate.', 'https://housing.sl.ua.edu/incoming-students/apply/', 'human', '2026-09-07T23:42:05.000Z', '2026-09-07T23:42:05.000Z');
INSERT INTO public.guidance_assets (id, rule_id, what, when_text, why, how, consequence, deep_link, generated_by, created_at, updated_at) VALUES ('guide_2e5db09aa08245ee8dfa88d99a3ff902', 'rule_863f6f11219243f6a118db1cd1389b59', 'Submit your Medical History Form and immunization records (MenACWY, MMR, Varicella, Tdap, TB screening).', 'Immediately upon admission — no fixed calendar date, but it can hold your registration if delayed.', 'Alabama requires proof of these immunizations before you can fully register for classes.', 'Print the required form from the Student Health Center section of myBama, have a healthcare provider complete and sign it, then scan and upload it back through myBama.', 'Incomplete or incorrectly formatted submissions are rejected outright, and a registration hold is possible.', 'https://cchs.ua.edu/shc/immunization/', 'human', '2026-09-07T23:42:05.001Z', '2026-09-07T23:42:05.001Z');
INSERT INTO public.observation_patterns (id, institution_id, workflow, url_pattern, signal, implies_state, related_checkpoint_code, confidence_threshold, created_at) VALUES ('obs_1a3beb0f307a4827b42f01fed3117826', 'inst_9eb0d203e0af4840875824c2696c13be', 'housing_application', 'housing.sl.ua.edu/*', 'application submitted', 'submitted', 'HOU-04', 0.7, '2026-09-07T23:42:05.001Z');
