INSERT INTO public.observation_patterns (id, institution_id, workflow, url_pattern, signal, implies_state, related_checkpoint_code, confidence_threshold, created_at) VALUES ('obs_67629f24ce5145089f8e872d0ef77fc2', 'inst_9eb0d203e0af4840875824c2696c13be', 'immunization_upload', 'mybama.ua.edu/*immunization*', 'compliant', 'complete', 'HLT-01', 0.7, '2026-09-07T23:42:05.002Z');
